#pragma scop
  const int BJ = 64;
  const int BI = 64;

  #pragma omp parallel
  {
    int kk;

    for (kk = 0; kk < _PB_N; kk++)
    {
      #pragma omp single
      {
        k = kk;
        nrm = SCALAR_VAL(0.0);
      }

      #pragma omp for reduction(+:nrm)
      for (i = 0; i < _PB_M; i++)
