      #pragma omp single
      {
        R[k][k] = SQRT_FUN(nrm);
      }

      #pragma omp for
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];

      #pragma omp for schedule(static)
      for (int jj = k + 1; jj < _PB_N; jj += BJ)
      {
